import { Hatchet } from '@hatchet-dev/typescript-sdk';

const hatchet = Hatchet.init();
const runId = process.env.ZEALT_RUN_ID || 'local';

export const workflow = hatchet.workflow({
  name: `linear-dag-${runId}`,
  on: {
    event: 'linear:trigger',
  },
});

workflow.step({
  name: 'step1',
  run: async (ctx) => {
    return { text: 'hello' };
  },
});

workflow.step({
  name: 'step2',
  parents: ['step1'],
  run: async (ctx) => {
    const step1Output = ctx.parentOutput('step1');
    return { text: step1Output.text + ' world' };
  },
});

workflow.step({
  name: 'step3',
  parents: ['step2'],
  run: async (ctx) => {
    const step2Output = ctx.parentOutput('step2');
    return { final: step2Output.text + '!' };
  },
});

