import { Hatchet } from '@hatchet-dev/typescript-sdk';
import { workflow } from './workflow';

const hatchet = Hatchet.init();
const runId = process.env.ZEALT_RUN_ID || 'local';

async function main() {
  const worker = await hatchet.worker(`linear-dag-worker-${runId}`, {
    workflows: [workflow],
  });
  await worker.start();
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

import fs from 'fs';
import { workflow } from './workflow';

async function main() {
  console.log('Triggering workflow...');
  const run = await workflow.run({});
  console.log('Waiting for workflow result...');
  const result = await run.result();

  // The DAG run result is keyed by task name
  // result.step3 should contain the output of step3
  const step3Output = result.step3;

  console.log('Final output:', step3Output);

  fs.writeFileSync('/tmp/result.json', JSON.stringify(step3Output));
  console.log('Result written to /tmp/result.json');
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

